// Etiqueta Despacho (60 x 60 mm): cabeçalho com logo centralizado (160 x 68),
// corpo com o destino em faixa preta, o produto em destaque, manipulação com data
// e hora, validade com data e peso líquido; rodapé igual ao da câmara fria.
// %destino_*% e %produto_*% (y, h, w, linhas) são calculados pelo firmware
// conforme o tamanho dos textos (não aparecem na tela).
static const char DEFAULT_TEMPLATE_DESPACHO[] = R"ZPL(^XA
^CI28
^PW480
^LL480
^LH0,0
^FX --- Etiqueta Despacho 60 x 60 mm: cabecalho, corpo e rodape ---
^FX --- Cabecalho: logo TotalFood centralizado (160 x 68); fica na memoria da impressora ---
^FO160,10^XGR:LOGODP.GRF,1,1^FS
^FO16,84^GB448,3,3^FS
^FX --- Corpo: destino em faixa preta, letra branca (fonte ajustada pelo firmware) ---
^FO16,90^GB448,42,42^FS
^FO16,%destino_y%^A0N,%destino_h%,%destino_w%^FB448,1,0,C^FR^FD%destino%^FS
^FX --- Corpo: produto em destaque (fonte, linhas e posicao calculadas pelo firmware) ---
^FO16,%produto_y%^A0N,%produto_h%,%produto_w%^FB448,%produto_linhas%,4,C^FD%produto%^FS
^FX --- Corpo: manipulacao com data e hora; validade so com a data; peso liquido ---
^FO16,216^A0N,24,20^FDMANIPULAÇÃO:^FS
^FO200,215^A0N,26,22^FB264,1,0,R^FD%manipulacao% %hora_manipulacao%^FS
^FO16,244^A0N,28,24^FDVALIDADE:^FS
^FO180,244^A0N,28,24^FB284,1,0,R^FD%validade%^FS
^FO16,274^A0N,28,24^FDPESO LÍQ.:^FS
^FO180,274^A0N,28,24^FB284,1,0,R^FD%peso_liq%^FS
^FO16,306^GB448,3,3^FS
^FX --- Rodape: igual a etiqueta de camara fria ---
^FO16,316^A0N,24,20^FB448,1,0,L^FDRESP.: %responsavel%^FS
^FO16,350^A0N,22,20^FDTOTAL FOOD ALIMENTOS^FS
^FO16,376^A0N,20,18^FDCNPJ: 17.053.741/0001-33^FS
^FO16,400^A0N,20,18^FDRUA MÁRIO GUEDES, 50^FS
^FO16,424^A0N,20,18^FDCEP 60811-012 - FORTALEZA, CE^FS
^PQ1
^XZ
)ZPL";
